-- The DO-GRIP insert code key (Code keys -> Parting -> DO-GRIP), from the
-- catalog's family designation; kept if one exists.
INSERT INTO "AppSetting" ("key", "value") VALUES ('codekey.dogrip', $ck${"title": "DO-GRIP insert code key – family designation", "subtitle": "Parting and grooving inserts (DGN / DGR / DGL; HG for 3 mm twisted geometry only)", "example": "DGR 3100JS-15D", "decoder": "do-grip", "sections": [{"key": "dg-family", "title": "Family", "sample": "DG", "rows": [{"code": "DG", "meaning": "DO-GRIP double-ended insert"}, {"code": "HG", "meaning": "For 3 mm twisted geometry only"}]}, {"key": "dg-hand", "title": "Hand of insert", "sample": "R", "rows": [{"code": "L", "meaning": "Left"}, {"code": "R", "meaning": "Right"}, {"code": "N", "meaning": "Neutral"}]}, {"key": "dg-variant", "title": "Insert type (optional)", "rows": [{"code": "C", "meaning": "DGNC type (e.g. DGN/DGNC/DGNM-C)"}, {"code": "M", "meaning": "DGNM type (e.g. DGNM J: single-ended PCD tipped)"}], "note": "Only some families have it, e.g. DGNC 3102C."}, {"key": "dg-width", "title": "Nominal insert width (x10 mm)", "sample": "31", "rows": [{"code": "##", "meaning": "Nominal insert width x 10 (e.g. 31 = 3.1 mm)"}]}, {"key": "dg-radius", "title": "Corner radii (x10 mm)", "sample": "00", "rows": [{"code": "##", "meaning": "Corner radii x 10 (e.g. 02 = 0.2 mm; 00 = none)"}]}, {"key": "dg-chip", "title": "Chipformer", "sample": "J", "rows": [{"code": "J", "meaning": "Soft materials, parting tubes, small diameters and thin-walled parts"}, {"code": "C", "meaning": "Bars, hard materials and tough applications"}, {"code": "UA", "meaning": "Cr-Ni alloys, low carbon steel and ductile materials at low feeds"}, {"code": "UT", "meaning": "Cr-Ni alloys, low carbon steel and ductile materials at low feeds"}, {"code": "W", "meaning": "Central ridged chipformer for hard materials and interrupted cuts"}, {"code": "P", "meaning": "Soft materials, thin and miniature parts"}, {"code": "Z", "meaning": "Very positive rake for tubes, thin-walled and small parts"}, {"code": "WP", "meaning": "Wiper design for high flatness and surface finish"}, {"code": "LF", "meaning": "Stainless steel"}, {"code": "LFT", "meaning": "Stainless steel"}, {"code": "MF", "meaning": "Soft and hard materials at medium feeds"}, {"code": "T", "meaning": "Ductile materials, steel and stainless steel"}, {"code": "B", "meaning": "Soft & ductile materials such as 100Cr6 (bearing industry), low to medium feeds"}], "note": "J, C, UA, UT and W as in the catalog's family designation; the others from the e-catalog's DO-GRIP families."}, {"key": "dg-sharp", "title": "Sharp corners (optional)", "sample": "S", "rows": [{"code": "S", "meaning": "Additional S – sharp corners (e.g. JS)"}]}, {"key": "dg-lead", "title": "Lead angle (KAPR)", "sample": "15", "rows": [{"code": "##", "meaning": "Lead angle in degrees (e.g. 15 = 15°)"}]}, {"key": "dg-degree", "title": "Degree", "sample": "D", "rows": [{"code": "D", "meaning": "Degree – the lead angle is given in degrees"}]}], "tables": [{"title": "Depth capacity for DGN/R-1002J insert on standard holders – to have no limit on the workpiece diameter up to 3 mm depth, grind the steel support under the insert (0.6 x 3.3 mm)", "columns": ["Depth T (mm)", "ØD max (mm)"], "rows": [["1.2", "No limit"], ["1.3", "830"], ["1.4", "218"], ["1.5", "126"], ["1.6", "88.4"], ["1.7", "68.2"], ["1.8", "55.6"], ["1.9", "46.9"], ["2.0", "40.7"], ["2.1", "36.0"], ["2.2", "32.3"], ["2.3", "29.3"], ["2.4", "26.7"], ["2.5", "24.8"], ["2.6", "23.2"], ["2.7", "21.7"], ["2.8", "20.5"], ["2.9", "19.4"], ["3.0", "18.4"]]}]}$ck$)
ON CONFLICT ("key") DO NOTHING;
